import{Z as a,e as t,f as n,a0 as s}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Frontend & Headless","description":"","frontmatter":{},"headers":[],"relativePath":"guides/frontend-headless/index.md","filePath":"guides/frontend-headless/index.md","lastUpdated":1782532814000}'),o={name:"guides/frontend-headless/index.md"};function r(i,e,d,l,h,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="frontend-headless" tabindex="-1">Frontend &amp; Headless <a class="header-anchor" href="#frontend-headless" aria-label="Permalink to &quot;Frontend &amp; Headless&quot;">​</a></h1><p>npm packages, React/Vue/Web Components, GraphQL, caching, and client events.</p><h2 id="building-a-headless-contact-form-with-formie-react" tabindex="-1"><a href="/guides/frontend-headless/building-a-headless-contact-form-with-formie-react">Building a Headless Contact Form with Formie React</a> <a class="header-anchor" href="#building-a-headless-contact-form-with-formie-react" aria-label="Permalink to &quot;[Building a Headless Contact Form with Formie React](/guides/frontend-headless/building-a-headless-contact-form-with-formie-react)&quot;">​</a></h2><p>This walkthrough takes you from a Formie contact form in Craft to a working React front end that loads, renders, and submits the form over REST or GraphQL — without Twig templates on the page.</p><h2 id="cached-forms-in-production" tabindex="-1"><a href="/guides/frontend-headless/cached-forms-in-production">Cached Forms in Production</a> <a class="header-anchor" href="#cached-forms-in-production" aria-label="Permalink to &quot;[Cached Forms in Production](/guides/frontend-headless/cached-forms-in-production)&quot;">​</a></h2><p>Statically cached pages can serve form HTML with stale CSRF tokens, request tokens, and render IDs — which produces random-looking submit failures. Formie refreshes those values automatically when static-cache support is enabled. This guide covers production setups for Twig-rendered forms, Blitz, Craft Cloud, and headless React/Vue apps.</p><h2 id="client-events-—-gtm-ga4-and-meta" tabindex="-1"><a href="/guides/frontend-headless/client-events-gtm-ga4-and-meta">Client Events — GTM, GA4, and Meta</a> <a class="header-anchor" href="#client-events-—-gtm-ga4-and-meta" aria-label="Permalink to &quot;[Client Events — GTM, GA4, and Meta](/guides/frontend-headless/client-events-gtm-ga4-and-meta)&quot;">​</a></h2><p>Form submissions are conversion events. Formie lets you configure analytics payloads in the form builder — no custom JavaScript required for the common GTM, GA4, and Meta setups. This walkthrough wires a contact form through Google Tag Manager, with notes for headless apps and multi-page forms.</p><h2 id="custom-client-event-templates" tabindex="-1"><a href="/guides/frontend-headless/custom-client-event-templates">Custom Client Event Templates</a> <a class="header-anchor" href="#custom-client-event-templates" aria-label="Permalink to &quot;[Custom Client Event Templates](/guides/frontend-headless/custom-client-event-templates)&quot;">​</a></h2><p>Register analytics presets for the form builder <strong>Tracking</strong> tab — author workflow and a SaaS example. Template properties, payload contract, and troubleshooting live in <a href="/developers/custom-client-event-templates">Custom Client Event Templates</a>.</p><h2 id="graphql-submission-flow-end-to-end" tabindex="-1"><a href="/guides/frontend-headless/graphql-submission-flow-end-to-end">GraphQL Submission Flow End-to-End</a> <a class="header-anchor" href="#graphql-submission-flow-end-to-end" aria-label="Permalink to &quot;[GraphQL Submission Flow End-to-End](/guides/frontend-headless/graphql-submission-flow-end-to-end)&quot;">​</a></h2><p>This walkthrough follows a contact form from GraphQL bootstrap through page navigation, token refresh, and final submission — the same flow <code>@verbb/formie-react</code> and <code>@verbb/formie-core</code> use internally. Use it when building a custom GraphQL client or debugging headless submit failures.</p><h2 id="vue-and-web-components-starter-walkthrough" tabindex="-1"><a href="/guides/frontend-headless/vue-and-web-components-starter-walkthrough">Vue and Web Components Starter Walkthrough</a> <a class="header-anchor" href="#vue-and-web-components-starter-walkthrough" aria-label="Permalink to &quot;[Vue and Web Components Starter Walkthrough](/guides/frontend-headless/vue-and-web-components-starter-walkthrough)&quot;">​</a></h2><p>Formie ships first-class packages for Vue and Web Components alongside React. This walkthrough covers the same four integration stories — server-rendered HTML vs client-rendered UI, REST vs GraphQL — using the official starters as the reference implementation.</p>',14)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
